'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < data.length && data.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < data.length) {
    const c = data.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

function readTree(n) {
  const graph = Array.from({ length: n }, () => []);
  for (let i = 0; i < n - 1; i++) {
    const a = nextInt() - 1;
    const b = nextInt() - 1;
    graph[a].push(b);
    graph[b].push(a);
  }
  return graph;
}

function getCenter(graph) {
  const n = graph.length;

  function bfs(start, needParent) {
    const dist = new Int32Array(n);
    dist.fill(-1);
    const parent = needParent ? new Int32Array(n) : null;
    const queue = new Int32Array(n);
    let head = 0;
    let tail = 0;
    queue[tail++] = start;
    dist[start] = 0;
    let farthest = start;

    while (head < tail) {
      const node = queue[head++];
      if (dist[node] > dist[farthest]) farthest = node;

      for (const next of graph[node]) {
        if (dist[next] !== -1) continue;
        dist[next] = dist[node] + 1;
        if (needParent) parent[next] = node;
        queue[tail++] = next;
      }
    }

    return { farthest, parent };
  }

  const endpointA = bfs(0, false).farthest;
  const result = bfs(endpointA, true);
  const endpointB = result.farthest;

  const path = [];
  for (let node = endpointB; ; node = result.parent[node]) {
    path.push(node);
    if (node === endpointA) break;
  }
  path.reverse();

  return path[Math.floor((path.length - 1) / 2)] + 1;
}

const n = nextInt();
const m = nextInt();
const circle = readTree(n);
const square = readTree(m);

console.log(`${getCenter(circle)} ${getCenter(square)}`);
